//! `application` (src/models/application/) against the database: scoping, ordering, paging.
//! Generated by `cargo offrails generate model applications request:references{request} pitch:text contact:string`.

use board::error::AppError;
use board::models::{Page, application};

use crate::factories;
use crate::support::TestApp;

#[tokio::test]
async fn find_for_sees_only_the_owners_applications() {
    let app = TestApp::new().await;
    let alice = factories::user(app.db(), "alice@example.com").await;
    let bob = factories::user(app.db(), "bob@example.com").await;
    let record = factories::application(app.db(), &alice).await;
    assert_eq!(
        application::find_for(app.db(), &alice, record.id)
            .await
            .unwrap(),
        record
    );
    assert!(matches!(
        application::find_for(app.db(), &bob, record.id).await,
        Err(AppError::NotFound)
    ));
    assert!(
        factories::reload_application(app.db(), record.id)
            .await
            .is_some()
    );
}

#[tokio::test]
async fn all_for_pages_newest_first() {
    let app = TestApp::new().await;
    let alice = factories::user(app.db(), "alice@example.com").await;
    let bob = factories::user(app.db(), "bob@example.com").await;
    let first = factories::application(app.db(), &alice).await;
    let second = factories::application(app.db(), &alice).await;
    let third = factories::application(app.db(), &alice).await;
    factories::application(app.db(), &bob).await;
    let (rows, more) = application::all_for(app.db(), &alice, Page::new(1, 2))
        .await
        .unwrap();
    assert_eq!(rows, vec![third, second]);
    assert!(more);
    let (rows, more) = application::all_for(app.db(), &alice, Page::new(2, 2))
        .await
        .unwrap();
    assert_eq!(rows, vec![first]);
    assert!(!more);
}

#[tokio::test]
async fn saved_application_validates_again() {
    let app = TestApp::new().await;
    let alice = factories::user(app.db(), "alice@example.com").await;
    let record = factories::application(app.db(), &alice).await;
    assert!(
        application::ApplicationParams::from(&record)
            .validate()
            .is_ok()
    );
}
